    <script type="text/javascript">
        $(document).ready(function(){
            var maxField = 20; //Input fields increment limitation
            var addButton = $('.add_button'); //Add button selector
            var wrapper = $('.loose-part-repeat'); //Input field wrapper
            var fieldHTML = '<div class="row">'+
                '<div class="col-md-2">'+
                '<div class="form-group">'+
                '<input type="text" name="part_no[]" class="form-control" placeholder="part_no"  required>'+
                '</div>'+
                '</div>'+
                '<div class="col">'+
                '<div class="form-group">'+
                '<textarea type="text" name="part_description[]" class="form-control" placeholder="Part description" rows="1" required></textarea>'+
                '</div>'+
                '</div>'+
                '<div class="col-md-1">'+
                '<div class="form-group">'+
                '<input type="text" name="qty[]" class="form-control" placeholder="QTY">'+
                '</div>'+
                '</div>'+
                '<div class="col">'+
                '<div class="form-group">'+
                '<textarea type="text" name="part_condition[]" class="form-control" placeholder="Part condition" rows="1"></textarea>'+
                '</div>'+
                '</div>'+
                '<div class="col">'+
                '<div class="form-group">'+
                '<div class="custom-file">'+
                '<input name="photograph[]" type="file" class="custom-file-input" id="customFileLang" lang="en">'+
                '<label class="custom-file-label" for="customFileLang">Photograph taken</label>'+
                '</div>'+
                '</div>'+
                '</div>'+
                '<div class="col-auto">'+
                '<a href="javascript:void(0);" class="btn btn-danger remove_button">-</a>'+
                '</div>'+
                '</div>'; //New input field html
            var x = 1; //Initial field counter is 1

            //Once add button is clicked
            $(addButton).click(function(){
                //Check maximum number of input fields
                if(x < maxField){
                    x++; //Increment field counter
                    $(wrapper).append(fieldHTML); //Add field html
                }
            });
            $('.select2').select2();
            //Once remove button is clicked
            $(wrapper).on('click', '.remove_button', function(e){
                e.preventDefault();
                $(this).parent().parent().remove(); //Remove field html
                x--; //Decrement field counter
            });
        });
    </script>

