                                                            '<label for="" class="form-control-label">Observation Point</label>'+
                                                            '<textarea type="text" name="observation[]" class="form-control" placeholder="Observation Point" rows="1"></textarea>'+
                                                        '</div>'+
                                                    '</div>'+

                                                    '<div class="col-4">'+
                                                        '<div class="form-group">'+
                                                            '<label for="" class="form-control-label">Remarks</label>'+
                                                            '<input type="text" name="remarks[]" class="form-control" placeholder="Remarks">'+
                                                        '</div>'+
                                                    '</div>'+

                                                    '<div class="col-auto">'+
                                '<a href="javascript:void(0);" class="btn btn-danger remove_button">-</a>'+
                                '</div>'+
                                '</div>');

                            x++; //text box increment
                        }
                        return false;

                        $(wrapper).on("click",".remove_button", function(e){ //user click on remove text
                            console.log(x);
                            if( x > 1 ) {
                                console.log(x);
                                $(this).parent('div').remove(); //remove text box
                                x--; //decrement textbox
                            }
                            return false;
                        })


                    });
                    //$('.select2').select2();
                    //Once remove button is clicked
                    $(wrapper).on('click', '.remove_button', function(e){
                        e.preventDefault();
                        $(this).parent().parent().remove(); //Remove field html
                        x--; //Decrement field counter
                    });
                });


            </script>

            <script type="text/javascript">
                $(document).ready(function(){
                    var maxField = 20; //Input fields increment limitation
                    var addButton = $('.add_inspection'); //Add button selector
                    var wrapper = $('.inspection-repeat'); //Input field wrapper

                    //alert(countafterfield);
                    //New input field html
                    var x = 0;
                    var FieldCount=0;
                    var countidlrclear =$('#countbushinspmea').val();

                    if(countidlrclear !== null){
                        x = countidlrclear -1;
                        FieldCount =countidlrclear -1;
                    }
                    if(isNaN (countidlrclear) ){
                        x = 0;
                        FieldCount=0;
                    }
                    console.log(x)
                    //Once add button is clicked
                    $(addButton).click(function(){


                        if(x <= maxField) //max input box allowed
                        {
                            FieldCount++; //text box added increment
                            //add input box
                            $(wrapper).append('<div class="row no-gutters">'+

                                                    '<div class="col-1">'+
                                                        '<div class="form-group">'+
                                                            '<label for="" class="form-control-label">Sr. No</label>'+
                                                            '<input type="text" name="slno[]" class="form-control" placeholder="Sr. No" required="">'+
                                                        '</div>'+
                                                    '</div>'+

                                                    '<div class="col-3">'+
                                                        '<div class="form-group">'+
                                                            '<label for="" class="form-control-label">Part Name</label>'+
                                                            '<textarea type="text" name="partname[]" class="form-control" placeholder="Part Name" rows="1"></textarea>'+
                                                        '</div>'+
                                                   '</div>'+

                                                    '<div class="col-2">'+
                                                        '<div class="form-group">'+
                                                            '<label for="" class="form-control-label">Failure Type</label>'+
                                                            '<input type="text" name="failuretype[]" class="form-control" placeholder="Failure Type">'+
                                                        '</div>'+
                                                    '</div>'+

                                                     '<div class="col-3">'+
                                                        '<div class="form-group">'+
                                                            '<label for="" class="form-control-label">Remarks</label>'+
                                                            '<input type="text" name="remarks[]" class="form-control" placeholder="Remarks">'+
                                                        '</div>'+
                                                    '</div>'+
                                                     '<div class="col-2">'+
                                                        '<div class="form-group">'+
                                                            '<label for="" class="form-control-label">Cannibalized Or Support</label>'+
                                                            '<input type="text" name="support[]" class="form-control" placeholder="Cannibalized Or Support">'+
                                                        '</div>'+
                                                    '</div>'+

                                                    '<div class="col-auto">'+
                                '<a href="javascript:void(0);" class="btn btn-danger remove_button">-</a>'+
                                '</div>'+
                                '</div>');

                            x++; //text box increment
                        }
                        return false;

                        $(wrapper).on("click",".remove_button", function(e){ //user click on remove text
                            console.log(x);
                            if( x > 1 ) {
                                console.log(x);
                                $(this).parent('div').remove(); //remove text box
                                x--; //decrement textbox
                            }
                            return false;
                        })


                    });
                    //$('.select2').select2();
                    //Once remove button is clicked
                    $(wrapper).on('click', '.remove_button', function(e){
                        e.preventDefault();
                        $(this).parent().parent().remove(); //Remove field html
                        x--; //Decrement field counter
                    });
                });


            </script>


